import { createSlice, PayloadAction } from "@reduxjs/toolkit";
import type { DiscountRequest, Order } from "@/types/orders";
import type {
  IDoctorFormData,
  IPatientFormData,
  IRecipientFormData,
} from "@/lib/interface";

type OrderDraftType = "eoppy" | "non_eoppy";

export interface OrderDraftState {
  type: OrderDraftType | null;

  // Only used when type === "eoppy"
  syntagiUploaded: { filename: string } | null;

  // Common fields for both types (same form)
  patient: IPatientFormData;
  recipient: IRecipientFormData;
  doctor: IDoctorFormData;
}

export interface OrdersState {
  orders: Order[];
  discountRequests: DiscountRequest[];
  draft: OrderDraftState;
}

function initialPatient(): IPatientFormData {
  return {
    amka: "",
    fullName: "",
    idNumber: "",
    phone: "",
    otp: "",
    email: "",
    dob: "",
    address: "",
    city: "",
    zip: "",
    deliverToOtherAddress: false,
    pickedUpByOther: false,
  };
}

function initialRecipient(): IRecipientFormData {
  return {
    reason: "",
    relation: "",
    fullName: "",
    idNumber: "",
    amka: "",
    afm: "",
    phone: "",
    address: "",
    city: "",
    zip: "",
  };
}

function initialDoctor(): IDoctorFormData {
  return {
    amka: "",
    fullName: "",
    afm: "",
    healthStructure: "",
    healthType: "",
    hasRefDoctor: true,
    refDoctorAmka: "",
    refDoctorFullName: "",
    refDoctorAfm: "",
  };
}

function initialDraft(): OrderDraftState {
  return {
    type: null,
    syntagiUploaded: null,
    patient: initialPatient(),
    recipient: initialRecipient(),
    doctor: initialDoctor(),
  };
}

const initialState: OrdersState = {
  orders: [
    {
      kind: "order",
      id: 56,
      recipeNo: "022025081477434",
      dateCreated: "17/12/2025",
      dateSubmitted: "29/12/2025",
      clientName: "ΓΑΒΑΘΟΠΟΥΛΟΥ ΜΑΡΙΑ",
      clientAmka: "27033301881",
      doctorName: "ΑΔΑΜΟΠΟΥΛΟΣ ΣΤΑΥΡΟΣ",
      doctorAmka: "20036600532",
      quantity: 2,
      status: "ΚΑΤΑΧΩΡΗΘΗΚΕ",
    },
  ],
  discountRequests: [
    {
      kind: "discountRequest",
      id: 58,
      recipeNo: "022025081551405",
      dateCreated: "18/12/2025",
      dateSubmitted: "29/12/2025",
      clientName: "ΜΑΝΑΓΛΙΩΤΗΣ ΠΑΝΑΓΙΩΤΗΣ",
      clientAmka: "10076204113",
      doctorName: "ΚΥΡΙΑΚΙΔΗΣ ΑΛΕΞΑΝΔΡΟΣ",
      doctorAmka: "20106600198",
      quantity: 1,
      requestedPrice: 5.93,
      status: "ΕΚΚΡΕΜΕΙ",
    },
  ],
  draft: initialDraft(),
};

const ordersSlice = createSlice({
  name: "orders",
  initialState,
  reducers: {
    approveDiscount(state, action: PayloadAction<number>) {
      const req = state.discountRequests.find((r) => r.id === action.payload);
      if (req) req.status = "ΕΓΚΡΙΘΗΚΕ";
    },
    denyDiscount(state, action: PayloadAction<number>) {
      const req = state.discountRequests.find((r) => r.id === action.payload);
      if (req) req.status = "ΑΠΟΡΡΙΦΘΗΚΕ";
    },

    // Draft flow (shared for both types)
    startDraft(state, action: PayloadAction<{ type: OrderDraftType }>) {
      state.draft = initialDraft();
      state.draft.type = action.payload.type;
    },
    setDraftSyntagiUploaded(state, action: PayloadAction<{ filename: string }>) {
      state.draft.syntagiUploaded = { filename: action.payload.filename };
    },
    patchDraftPatient(state, action: PayloadAction<Partial<IPatientFormData>>) {
      state.draft.patient = { ...state.draft.patient, ...action.payload };
    },
    patchDraftRecipient(state, action: PayloadAction<Partial<IRecipientFormData>>) {
      state.draft.recipient = { ...state.draft.recipient, ...action.payload };
    },
    patchDraftDoctor(state, action: PayloadAction<Partial<IDoctorFormData>>) {
      state.draft.doctor = { ...state.draft.doctor, ...action.payload };
    },

    // Demo submit: here you can call API later.
    submitDraft(state) {
      // Keep it minimal for now; you can build the real payload here.
      state.draft = initialDraft();
    },
  },
});

export const {
  approveDiscount,
  denyDiscount,
  startDraft,
  setDraftSyntagiUploaded,
  patchDraftPatient,
  patchDraftRecipient,
  patchDraftDoctor,
  submitDraft,
} = ordersSlice.actions;

export default ordersSlice.reducer;
